import React, { useState } from "react";
import "./App.css";

function App() {
  const [disease, setDisease] = useState("");
  const [intent, setIntent] = useState("");
  const [location, setLocation] = useState("");

  const [loading, setLoading] = useState(false);
  const [data, setData] = useState(null);
  const [error, setError] = useState("");

  // 🧠 PARSE LLM SECTIONS
  const parseSummary = (text) => {
    const sections = text.split(/\d\.\s/).filter(Boolean);

    return sections.map((section) => {
      const lines = section.split("\n");
      const title = lines[0];
      const content = lines.slice(1).join(" ");

      return { title, content };
    });
  };

  // 🚀 SUBMIT
  const handleSubmit = async () => {
    if (!disease.trim()) {
      alert("Please enter disease");
      return;
    }

    setLoading(true);
    setError("");
    setData(null);

    try {
      const response = await fetch("http://127.0.0.1:8000/analyze", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          disease,
          intent,
          location,
        }),
      });

      const result = await response.json();

      if (!response.ok) {
        throw new Error(result.error || "Something went wrong");
      }

      setData(result);
    } catch (err) {
      console.error(err);
      setError("Failed to fetch AI insights");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="app-container">

      {/* LEFT SIDEBAR */}
      <div className="sidebar">
        <h2>Curalink X</h2>

        <input
          type="text"
          placeholder="Disease (e.g. cancer)"
          value={disease}
          onChange={(e) => setDisease(e.target.value)}
        />

        <div className="stats">
          <h3>Stats</h3>
          <p>📄 Papers: {data?.meta?.total_papers || 0}</p>
          <p>🧪 Trials: {data?.meta?.total_trials || 0}</p>
        </div>
      </div>

      {/* MAIN */}
      <div className="main">
        <h1>🧠 AI Medical Research Copilot</h1>
        <p className="subtitle">
          Turn complex medical queries into structured insights
        </p>

        <textarea
          placeholder="Enter intent (e.g. how to cure cancer)"
          value={intent}
          onChange={(e) => setIntent(e.target.value)}
        />

        <input
          type="text"
          placeholder="Location (e.g. USA)"
          value={location}
          onChange={(e) => setLocation(e.target.value)}
        />

        <button onClick={handleSubmit} disabled={loading}>
          {loading ? "⏳ Thinking..." : "Send message"}
        </button>

        {error && <p className="error">{error}</p>}

        {/* RESULTS */}
        {data && (
          <div className="results">

            {/* 🧠 INSIGHTS (STRUCTURED) */}
            <div className="card">
              <h2>🧠 AI Insights</h2>

              {parseSummary(data.insights).map((sec, i) => (
                <div key={i} className="summary-block">
                  <h4>📌 {sec.title}</h4>
                  <p>{sec.content}</p>
                </div>
              ))}
            </div>

            {/* 📄 PUBLICATIONS */}
            <div className="card">
              <h2>📄 Top Research Papers</h2>

              {data.publications.length === 0 ? (
                <p>No research papers found</p>
              ) : (
                data.publications.map((pub, i) => (
                  <div key={i} className="item">
                    <h4>{pub.title}</h4>
                    <p>{pub.year} • {pub.source}</p>
                    <a href={pub.link} target="_blank" rel="noreferrer">
                      View Paper →
                    </a>
                  </div>
                ))
              )}
            </div>

            {/* 🧪 TRIALS */}
            <div className="card">
              <h2>🧪 Clinical Trials</h2>

              {data.clinical_trials.length === 0 ? (
                <p>No trials found</p>
              ) : (
                data.clinical_trials.map((t, i) => (
                  <div key={i} className="item">
                    <h4>{t.title}</h4>
                    <p>Status: {t.status}</p>
                  </div>
                ))
              )}
            </div>

          </div>
        )}
      </div>
    </div>
  );
}

export default App;
